describe('Checkout Form Card Expiry Validation', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should validate card expiry in MM/YY format and display error for invalid format', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/checkout/submit').as('checkoutSubmit');

    // Fill in form with valid card details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');
    cy.get('[data-testid="card-holder-name-input"]').type('John Doe');

    // Submit the form
    cy.get('[data-testid="submit-checkout-button"]').click();

    // Wait for API call
    cy.wait('@checkoutSubmit');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Order placed successfully');

    // Verify form is cleared or redirected
    cy.get('[data-testid="card-number-input"]').should('have.value', '');
  });

  it('should display error message when card expiry is in invalid format', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/checkout/submit').as('checkoutSubmit');

    // Fill in form with valid card details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="card-cvc-input"]').type('123');
    cy.get('[data-testid="card-holder-name-input"]').type('John Doe');

    // Attempt to submit with invalid expiry format (e.g., DD/MM/YY)
    cy.get('[data-testid="card-expiry-input"]').type('25/12');
    cy.get('[data-testid="submit-checkout-button"]').click();

    // Wait for API call
    cy.wait('@checkoutSubmit');

    // Verify error message is displayed
    cy.get('[data-testid="expiry-error-message"]')
      .should('be.visible')
      .should('contain', 'Please enter expiry date in MM/YY format');

    // Verify form is not submitted
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify card expiry input still has the invalid value
    cy.get('[data-testid="card-expiry-input"]').should('have.value', '25/12');
  });
});
